int[] tab = {10, 25, 7, 42, 3};

// do przodu, z indeksem
for (int i = 0; i < tab.length; i++) {
    System.out.println("indeks " + i + ": " + tab[i]);
}

// wzbogacona petla - gdy indeks nie jest potrzebny
for (int wartosc : tab) {
    System.out.println(wartosc);
}

// od tylu
for (int i = tab.length - 1; i >= 0; i--) {
    System.out.println(tab[i]);
}

int[] tab = {3, 1, 4, 1, 5, 9, 2, 6};
int[] prefixSum = new int[tab.length + 1]; // prefixSum[i] = suma tab[0..i-1]
for (int i = 0; i < tab.length; i++) {
    prefixSum[i + 1] = prefixSum[i] + tab[i];
}

// suma przedzialu [a, b] (wlacznie) w O(1):
int sumaPrzedzialu(int a, int b) {
    return prefixSum[b + 1] - prefixSum[a];
}
// np. suma tab[2..5] = 4+1+5+9 = 19 -> sumaPrzedzialu(2, 5) zwraca 19 BEZ liczenia od nowa

